class TTLCache:
    def __init__(self, capacity, ttl_seconds, clock):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.clock = clock
        self._entries = {}  # key -> [value, expire_at]

    def _evict(self, now):
        # Drop expired entries first so live entries are only evicted when needed.
        for key in list(self._entries):
            if self._entries[key][1] <= now:
                del self._entries[key]
        # Evict the least-recently-used live entry (first in insertion order)
        # until we are back at or under capacity.
        while len(self._entries) > self.capacity:
            key = next(iter(self._entries))
            del self._entries[key]

    def get(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, expire_at = entry
        if self.clock() >= expire_at:
            del self._entries[key]
            return None
        # Refresh recency by moving the entry to the end.
        del self._entries[key]
        self._entries[key] = entry
        return value

    def put(self, key, value):
        now = self.clock()
        if key in self._entries:
            del self._entries[key]
        self._entries[key] = [value, now + self.ttl_seconds]
        if len(self._entries) > self.capacity:
            self._evict(now)

